      "required": false,
      "description": "Overrides the highlighted today."
    },
    {
      "name": "locale",
      "type": "string",
      "required": false,
      "defaultValue": "en-US",
      "description": "Locale for the trigger label and the grid."
    },
    {
      "name": "weekStartsOn",
      "type": "0 | 1",
      "required": false,
      "defaultValue": "0",
      "description": "Week start for the panel."
    },
    {
      "name": "placeholder",
      "type": "string",
