      "relationship": "The panel is a Calendar; use it directly for an inline grid",
      "example": "<Calendar value={date} onValueChange={setDate} />"
    },
    {
      "component": "FormField",
      "relationship": "Wrap with FormField for label, hint and error wiring",
      "example": "<FormField label=\"Date\"><DatePickerPopover /></FormField>"
    }
  ],
  "relatedComponents": [
