    "DateRangePicker",
    "FormField"
  ],
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.9.0",
  "sourceDir": "date-picker-popover",
  "exportName": "DatePickerPopover"
